// The faces of the 2029 document (ZURIEL 16.11.2026: "גופנים: עברית וניקוד קריאים, בלי שינוי פריסה כשהגופן מגיע"). Hebrew text in Rubik must
// never be drawn from two files arriving at different times: the frame's Hebrew file carries the spaces, digits and punctuation of Hebrew
// text (a phone row of chips wrapped when the spaces came from the Latin file, Post 192), and the Latin file only Latin letters. The local
// stand-ins cover exactly the same characters at every weight, so whichever face is drawing, every character has a measured width.
// Generated by docs/reviews/old-post-article-first-20261116/fonts/rubik-faces.py.
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync, existsSync } from "node:fs";
import { TYPEFACE } from "../src/lib/designTokens.js";

const html = readFileSync(new URL("../2029.html", import.meta.url), "utf8");
const faces = [...html.matchAll(/@font-face\s*\{([^}]*)\}/g)].map(([, body]) => Object.fromEntries([...body.matchAll(/([a-z-]+):\s*([^;]+);/g)].map(([, key, value]) => [key, value.trim()])));
const chars = range => { const out = new Set(); for (const part of String(range).split(",")) { const [a, b] = part.trim().slice(2).split("-"); for (let c = parseInt(a, 16); c <= parseInt(b || a, 16); c += 1) out.add(c); } return out; };
const union = sets => sets.reduce((all, set) => { for (const c of set) all.add(c); return all; }, new Set());
const disjoint = sets => sets.every((a, i) => sets.slice(i + 1).every(b => [...a].every(c => !b.has(c))));
const same = (a, b) => a.size === b.size && [...a].every(c => b.has(c));
const GOOGLE = union([chars("U+0307-0308,U+0590-05FF,U+200C-2010,U+20AA,U+25CC,U+FB1D-FB4F"),
  chars("U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD")]);

test("Rubik: the Hebrew file answers for the spaces, digits and punctuation of Hebrew text; the two files never overlap", () => {
  const rubik = faces.filter(face => face["font-family"] === "'Rubik'");
  assert.equal(rubik.length, 2);
  const hebrew = rubik.find(face => face.src.includes("/fonts/Rubik-Hebrew-Common.woff2")), latin = rubik.find(face => face.src.includes("/fonts/Rubik-Latin.woff2"));
  assert.ok(hebrew && latin);
  const h = chars(hebrew["unicode-range"]), l = chars(latin["unicode-range"]);
  assert.ok(disjoint([h, l]), "no character is in both files");
  assert.ok(same(union([h, l]), GOOGLE), "together they cover what Google's split covered");
  for (const c of "  0123456789.,:;?!()-\"'/%+=[]אתְּ״·–—…₪") assert.ok(h.has(c.codePointAt(0)), `Hebrew file covers ${JSON.stringify(c)}`);
  for (const c of "AZaz") assert.ok(l.has(c.codePointAt(0)), `Latin file covers ${c}`);
  for (const face of rubik) { assert.equal(face["font-display"], "swap"); assert.equal(face["font-weight"], "400 900"); }
  assert.ok(existsSync(new URL("../public/fonts/Rubik-Hebrew-Common.woff2", import.meta.url)));
  assert.match(html, /<link rel="preload" href="\/fonts\/Rubik-Hebrew-Common\.woff2" as="font" type="font\/woff2" crossorigin \/>/);
  assert.doesNotMatch(html, /rel="preload" href="\/fonts\/Rubik-Latin\.woff2"/, "the Latin letters are not preloaded");
});

test("the local stand-in for Rubik covers the same characters at every weight from 1 to 1000, by class, without gaps", () => {
  const stand = faces.filter(face => face["font-family"] === "'Sod Rubik Fallback'");
  const buckets = new Map();
  for (const face of stand) { const list = buckets.get(face["font-weight"]) || []; list.push(face); buckets.set(face["font-weight"], list); }
  const bounds = [...buckets.keys()].map(key => key.split(" ").map(Number)).sort((a, b) => a[0] - b[0]);
  assert.equal(bounds[0][0], 1); assert.equal(bounds.at(-1)[1], 1000);
  bounds.forEach(([, end], index) => { if (index < bounds.length - 1) assert.equal(bounds[index + 1][0], end + 1, `weights after ${end}`); });
  assert.equal(bounds.length, 6, "one bucket per Rubik weight 400–900");
  for (const [weight, list] of buckets) {
    const sets = list.map(face => chars(face["unicode-range"]));
    assert.equal(list.length, 4, `${weight}: Hebrew, Latin and punctuation, digits, space`);
    assert.ok(disjoint(sets), `${weight}: classes never overlap`);
    assert.ok(same(union(sets), GOOGLE), `${weight}: covers every character Rubik covers`);
    for (const face of list) {
      assert.match(face.src, /^local\('Arial( Bold)?'\)/);
      for (const key of ["size-adjust", "ascent-override", "descent-override", "line-gap-override"]) assert.match(face[key] || "", /^\d+(\.\d)?%$/, `${weight} ${key}`);
    }
  }
});

test("every text stack goes from Rubik to its own stand-in, never to another family's", () => {
  assert.match(TYPEFACE.ui, /^'Rubik','Sod Rubik Fallback',/);
  assert.match(TYPEFACE.display, /^'Rubik','Sod Rubik Fallback',/);
  assert.match(TYPEFACE.body, /^'Noto Sans Hebrew','Sod Hebrew Fallback','Rubik','Sod Rubik Fallback',/);
  assert.match(html, /font-family:'Noto Sans Hebrew','Sod Hebrew Fallback','Rubik','Sod Rubik Fallback',Arial,sans-serif;/);
  assert.match(readFileSync(new URL("../src/components/experience2029/opening2029.css", import.meta.url), "utf8"), /'Noto Sans Hebrew','Sod Hebrew Fallback',Rubik,'Sod Rubik Fallback',Arial,sans-serif/);
  assert.equal(/Sod Latin Fallback/.test(html), false);
});
